    let out = '<div class="cd-hint" style="margin:0 0 14px">Downloads every group-stage match, every knockout match, and each category\'s champion — across Men\'s, Women\'s and Mixed doubles. Best run once the tournament (or a category) has wrapped up, but it works at any point and just reflects whatever has been entered so far.</div>';
